(function(root){
const tutorialKey=c=>`inkfang-guide-v5-${c.control}-${c.skill}`;
const needsTutorial=(c,read)=>!read(tutorialKey(c),false);
function example(c){const cases={numbers:{target:c.control==='voice'?'98':'ninety-eight',answer:'98',say:'ninety-eight'},mixed:{target:c.control==='voice'?'98':'ninety-eight',answer:'98',say:'ninety-eight'},letters:{target:'B',answer:'B',say:'bee'},words:{target:c.control==='voice'?'CAT':'An animal that says “meow”.',answer:'CAT',say:'cat'},spelling:{target:'PARIS',answer:'PARIS',say:'Paris'},ipa:{target:'/kæt/',answer:'CAT',say:'cat'}};return cases[c.skill]||cases.numbers;}
function guidePages(c){const e=example(c),numeric=['numbers','mixed'].includes(c.skill);const first=c.control==='voice'?{title:'Look. Then say it.',text:c.skill==='ipa'?'Read the IPA transcription and say the whole word. /kæt/ is “cat”.':c.skill==='letters'?'Say the letter’s name aloud. For B, say “bee”.':`Say the ${numeric?'number':'word'} shown. You can name several visible targets in one phrase.`}:{title:numeric?'Read the number words.':'Read your target.',text:numeric?'A monster shows “ninety-eight”. Your answer is 98 — digits only. Typing the number words does not count.':c.skill==='words'?'Read the clue and work out the word. An animal that says “meow” is CAT.':'Read the name or place and spell it with CAPITAL letters.'};const second=c.control==='type'?{title:numeric?'Type digits, not words.':'Type the full answer.',text:`Touchscreens use compact game keys to save space. For a device keyboard, switch to English and turn off UniKey / Vietnamese input. Type ${e.answer}. A complete answer fires immediately unless it could still become another active target. Keep typing for longer targets. Enter is an optional shortcut.`}:{title:'Say a string of answers.',text:`Allow microphone access and say “${e.say}”. Name several targets in a row to attack them together. Stable speech updates can fire before the browser finishes the sentence.`};const third={title:'Bigger beasts. Bigger spells.',text:'Start with two hearts. Armoured monsters reveal a new target after each correct hit. Bosses take twelve hits. Ten answer-earned kills charge Inkstorm: clear ordinary monsters and remove six boss HP. Life Spirits restore one heart.'};return[first,second,third];}
function badgeFor({kills,bestCombo}){if(kills>=30&&bestCombo>=12)return{name:'INK LEGEND',glyph:'S',goal:50};if(kills>=20)return{name:'SWARM BREAKER',glyph:'A',goal:30};if(kills>=10)return{name:'LINE GUARD',glyph:'B',goal:20};return{name:'ROOKIE RISING',glyph:'C',goal:10};}
root.InkOnboarding={tutorialKey,needsTutorial,example,guidePages,badgeFor};if(typeof module!=='undefined')module.exports=root.InkOnboarding;
})(typeof window!=='undefined'?window:globalThis);
